// MCP tools for batch 75 (3-Nov-2026): mazes and dungeon maps.
// The pure cores come from src/tools_core75.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/
// maze-core-75a.js, draw-75a.js, dungeon-core-75a.js) — one source of truth with the /tools/ pages maze-generator and dungeon-map-generator.
// Stateless: no D1/R2, no fetch. Both are deterministic by seed.
import { MGD75A } from "./tools_core75.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => ({ content: [{ type: "text", text }], structuredContent });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const fence = (lang, s) => "```" + lang + "\n" + String(s).replace(/\n$/, "") + "\n```";
const OUT_CAP = 120 * 1024;
const num = (v) => (v === undefined || v === null || v === "" ? undefined : Number(v));
const fin = (v) => Number.isFinite(num(v));
const int = (v, a, b) => Number.isInteger(num(v)) && num(v) >= a && num(v) <= b;
const Z = MGD75A.maze, DG = MGD75A.dgn, DR = MGD75A.draw;
const SHAPES = Z.SHAPES.slice(), ALGOS = Z.ALGOS.slice(), DIFFS = Object.keys(Z.DIFF);
const DSIZES = Object.keys(DG.SIZES), DSTYLES = Object.keys(DG.STYLES);
const seedOf = (s, d) => (s !== undefined && String(s).trim() ? str(s, 40) : d);
const rseed = () => Math.random().toString(36).slice(2, 8);
// the cores write 2-decimal coordinates; 1 decimal is invisible at these sizes and keeps more mazes under the cap
const round1 = (svg) => svg.replace(/ d="[^"]*"/g, (d) => d.replace(/(\d+\.\d)\d/g, "$1"));

export const TOOL_DEFS = [
  {
    name: "make_maze",
    description: "Use when a puzzle sheet, activity book, game or classroom needs a maze: rectangle, circle, hexagon or triangle, carved by recursive backtracker, Prim, Kruskal or Wilson, by size or difficulty, with optional loops and the solution path. Same seed = same maze. Returns the SVG and stats (cells, dead ends, solution length).",
    inputSchema: {
      type: "object",
      properties: {
        shape: { type: "string", enum: SHAPES, description: "Default rect." },
        difficulty: { type: "string", enum: DIFFS, description: "Sets size (default medium)." },
        size: { type: "integer", description: "Cells across 2-120 (instead of difficulty)." },
        algorithm: { type: "string", enum: ALGOS, description: "Default backtracker." },
        seed: { type: "string", description: "Default random." },
        loops: { type: "number", description: "% extra openings 0-50 (default 0 = perfect maze)." },
        show_solution: { type: "boolean" },
      },
    },
    annotations: RO("Maze"),
  },
  {
    name: "make_dungeon",
    description: "Use when a D&D / tabletop session or game needs a dungeon map: seeded rooms joined by corridors (scattered or BSP layout), doors (wooden, locked, secret, archway), stairs up and down, traps, a 5 ft grid and rooms numbered by distance from the entrance, in classic blue, blueprint, parchment or ink. Returns the SVG and a numbered room key.",
    inputSchema: {
      type: "object",
      properties: {
        seed: { type: "string", description: "Default random." },
        size: { type: "string", enum: DSIZES, description: "Default medium." },
        layout: { type: "string", enum: ["rooms", "bsp"] },
        rooms: { type: "integer", description: "Target 2-60." },
        loops: { type: "number", description: "% extra corridors 0-100 (default 15)." },
        traps: { type: "integer", description: "0-20 (default 3)." },
        wide: { type: "boolean", description: "2-square corridors." },
        style: { type: "string", enum: DSTYLES }, title: { type: "string" }, grid: { type: "boolean" },
      },
    },
    annotations: RO("Dungeon map"),
  },
];

export const NEXT75 = {
  make_maze: "Next step: open the maze generator link to print 1-6 mazes per Letter or A4 page with answer sheets as a PDF.",
  make_dungeon: "Next step: open the dungeon map link to reroll rooms, change the style and export a print-ready PDF with the room key.",
};

// ---- maze
function maze(a) {
  if (a.shape !== undefined && !SHAPES.includes(a.shape)) return err("shape must be one of: " + SHAPES.join(", ") + ".");
  if (a.algorithm !== undefined && !ALGOS.includes(a.algorithm)) return err("algorithm must be one of: " + ALGOS.join(", ") + ".");
  if (a.difficulty !== undefined && !DIFFS.includes(a.difficulty)) return err("difficulty must be one of: " + DIFFS.join(", ") + ".");
  if (a.size !== undefined && !int(a.size, 2, 120)) return err("size must be an integer 2-120.");
  if (a.loops !== undefined && !(fin(a.loops) && num(a.loops) >= 0 && num(a.loops) <= 50)) return err("loops must be 0-50 (%).");
  const seed = seedOf(a.seed, rseed()), size = a.size !== undefined ? num(a.size) : Z.DIFF[a.difficulty || "medium"];
  const m = Z.generate({ shape: a.shape, algo: a.algorithm, seed, size, loops: fin(a.loops) ? num(a.loops) : 0 });
  const st = Z.stats(m), sol = a.show_solution === true, page = `${T}/maze-generator/`;
  const svg = round1(Z.svg(m, { solution: sol }));
  const dims = m.shape === "rect" ? `${m.size.w} × ${m.size.h} cells` : m.shape === "circle" ? `${m.size.rings} rings` : m.shape === "hex" ? `hex board radius ${m.size.rad}` : `${m.size.rows} rows`;
  const lines = [`**Maze (${m.shape}, ${m.algo}, seed ${seed}): ${dims}, ${st.cells} cells, ${st.deadEnds} dead ends, solution ${st.solution} cells long${m.loops ? `, ${Math.round(m.loops * 100)}% loops` : " (perfect maze: one route)"}.**`];
  const sc = { seed, shape: m.shape, algorithm: m.algo, size: m.size, cells: st.cells, passages: st.passages, dead_ends: st.deadEnds, solution_length: st.solution, loops_pct: Math.round(m.loops * 100), show_solution: sol, page };
  if (svg.length <= OUT_CAP) { lines.push(`SVG (${Math.round(svg.length / 1024)} KB${sol ? ", solution in red" : ""}; green = start, red = exit):`, fence("svg", svg)); sc.svg = svg; }
  else { lines.push(`The SVG (${Math.round(svg.length / 1024)} KB) is too large to return inline: use a smaller size, or open the page with seed ${seed} to download it.`); sc.svg_too_large = true; }
  lines.push("Printable PDF (1-6 per page, answer pages): " + page);
  return ok(lines.join("\n"), sc);
}

// ---- dungeon
function dungeon(a) {
  if (a.size !== undefined && !DSIZES.includes(a.size)) return err("size must be one of: " + DSIZES.join(", ") + ".");
  if (a.style !== undefined && !DSTYLES.includes(a.style)) return err("style must be one of: " + DSTYLES.join(", ") + ".");
  if (a.layout !== undefined && !["rooms", "bsp"].includes(a.layout)) return err("layout must be rooms or bsp.");
  if (a.rooms !== undefined && !int(a.rooms, 2, 60)) return err("rooms must be an integer 2-60.");
  if (a.traps !== undefined && !int(a.traps, 0, 20)) return err("traps must be an integer 0-20.");
  if (a.loops !== undefined && !(fin(a.loops) && num(a.loops) >= 0 && num(a.loops) <= 100)) return err("loops must be 0-100 (%).");
  const seed = seedOf(a.seed, rseed());
  const o = { seed, size: a.size, layout: a.layout, rooms: a.rooms === undefined ? undefined : num(a.rooms), loops: fin(a.loops) ? num(a.loops) : undefined, traps: a.traps === undefined ? undefined : num(a.traps), wide: a.wide === true };
  Object.keys(o).forEach((k) => o[k] === undefined && delete o[k]);
  const m = DG.generate(o), title = a.title !== undefined ? str(a.title, 60) : undefined;
  const dopt = { style: a.style, title, grid: a.grid === false ? "no" : undefined };
  let svg = round1(DR.svg(DG.draw(m, dopt), title || "Dungeon map")), hatchOff = false;
  if (svg.length > OUT_CAP) { svg = round1(DR.svg(DG.draw(m, Object.assign({}, dopt, { hatch: "no" })), title || "Dungeon map")); hatchOff = true; }
  const page = `${T}/dungeon-map-generator/`, key = DG.key(m).map((k) => k.text);
  const dc = {}; m.doors.forEach((d) => { dc[d.kind] = (dc[d.kind] || 0) + 1; });
  const rooms = m.rooms.slice().sort((p, q) => p.num - q.num).map((r) => ({ num: r.num, x: r.x, y: r.y, w: r.w, h: r.h, ft: [r.w * 5, r.h * 5], distance: r.dist, content: r.content }));
  const stairs = m.stairs.map((s) => ({ kind: s.kind, room: m.rooms[s.room] ? m.rooms[s.room].num : null, x: s.x, y: s.y }));
  const lines = [`**Dungeon (seed ${seed}, ${a.layout || "rooms"} layout, ${m.W} × ${m.H} squares = ${m.W * 5} × ${m.H * 5} ft): ${rooms.length} rooms numbered by distance from the entrance, ${m.corridors.length} corridors, ${m.doors.length} doors, ${m.traps.length} traps; stairs up in room ${stairs.filter((s) => s.kind === "up").map((s) => s.room).join(", ")}, down in room ${stairs.filter((s) => s.kind === "down").map((s) => s.room).join(", ")}.**`,
    "Room key:", ...key.filter(Boolean).map((k) => "- " + k)];
  const sc = { seed, layout: a.layout || "rooms", size: a.size || "medium", squares: [m.W, m.H], feet: [m.W * 5, m.H * 5], rooms, corridors: m.corridors.length,
    doors: { door: dc.door || 0, locked: dc.locked || 0, secret: dc.secret || 0, arch: dc.arch || 0 }, stairs, traps: m.traps.length, connected: !!m.connected, style: a.style || "classic", page };
  if (svg.length <= OUT_CAP) { lines.push(`SVG (${Math.round(svg.length / 1024)} KB, 1 square = 5 ft${hatchOff ? ", rock hatching off to fit" : ""}):`, fence("svg", svg)); sc.svg = svg; }
  else { lines.push(`The SVG is too large to return inline: open the page with seed ${seed} to download it.`); sc.svg_too_large = true; }
  lines.push("Reroll, restyle and print-ready PDF with the key: " + page);
  return ok(lines.join("\n"), sc);
}

const HANDLERS = { make_maze: maze, make_dungeon: dungeon };
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools75Tool(name) { return NAMES.has(name); }
export async function callTools75Tool(name, a) {
  a = a && typeof a === "object" ? a : {};
  try {
    if (HANDLERS[name]) return HANDLERS[name](a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}
